const first = $input.first().json;
const src = String(first.data ?? first.body ?? '');

const titleMatch = src.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const pageTitle = titleMatch ? titleMatch[1].trim() : '';

const text = src
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<nav[\s\S]*?<\/nav>/gi, ' ')
  .replace(/<footer[\s\S]*?<\/footer>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

const form = $('Blog Input Form').first().json;

return [{
  json: {
    article_text: (pageTitle ? pageTitle + '\n\n' : '') + text.slice(0, 8000),
    blog_url: form['Blog URL'] || '',
    featured_image_url: form['Featured Image URL'] || ''
  }
}];

const form = $('Blog Input Form').first().json;

return [{
  json: {
    article_text: String(form['Blog Content'] || '').slice(0, 8000),
    blog_url: form['Blog URL'] || '',
    featured_image_url: form['Featured Image URL'] || ''
  }
}];

const item = $input.first().json;

const article = String(item.article_text || '').trim();
const blogUrl = item.blog_url || '';

if (!article) {
  throw new Error('No blog content found. Fill in either the Blog URL field or the Blog Content field in the form.');
}

const prompt = [
  'Blog Content:',
  article,
  '',
  'Blog URL (include this as the call to action link where it fits naturally): ' + (blogUrl || 'not provided'),
  '',
  'Write platform-specific social media captions promoting this blog. Return strictly in JSON:',
  '{',
  '  "linkedin": "professional tone, under 200 words, strong first line hook, ends with a question, 3 hashtags",',
  '  "twitter": "under 260 characters, hook-driven, 2 hashtags",',
  '  "twitter_thread": [array of 5 to 7 tweets, each under 270 characters, tweet 1 is the hook, last tweet has the blog link and a call to action],',
  '  "facebook": "conversational tone, under 150 words, no hashtags",',
  '  "instagram": "casual tone, under 150 words, line breaks for readability, 8 relevant hashtags at the end",',
  '  "threads": "casual and punchy, under 480 characters",',
  '  "pinterest": { "title": "under 90 characters, keyword rich", "description": "under 480 characters, keyword rich, natural language" },',
  '  "youtube_community": "under 120 words, friendly, ends with a question to drive comments",',
  '  "reddit": { "title": "under 280 characters, no clickbait, states the value plainly", "body": "under 150 words, genuinely useful and non-promotional in tone, mentions the link once at the end" },',
  '  "image_alt_text": "under 120 characters, descriptive alt text for the featured image"',
  '}',
  '',
  'Rules:',
  '- Adapt tone per platform but keep the core message consistent.',
  '- Every caption must give a reason to click through to the blog.',
  '- No generic filler like "check this out".',
  '- Do not use em dashes anywhere in the output.',
  '- Return the JSON object only, no explanations and no markdown code fences.'
].join('\n');

return [{
  json: {
    prompt,
    blog_url: blogUrl,
    featured_image_url: item.featured_image_url || ''
  }
}];

const res = $input.first().json;

let raw = res.output ?? res.text ?? res.content ?? '';
if (typeof raw === 'object' && raw !== null) {
  raw = JSON.stringify(raw);
}
raw = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();

let c;
try {
  c = JSON.parse(raw);
} catch (e) {
  return [{ json: { html: '<html><body style="font-family:sans-serif;padding:32px"><h2>Could not parse the AI response</h2><pre style="white-space:pre-wrap;background:#f4f5f7;padding:16px;border-radius:8px">' + raw.replace(/</g, '&lt;') + '</pre></body></html>' } }];
}

const form = $('Blog Input Form').first().json;
const imageUrl = form['Featured Image URL'] || '';
const blogUrl = form['Blog URL'] || '';

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

let cardId = 0;
const card = (platform, body, note) => {
  if (!body) return '';
  cardId++;
  const id = 'cap' + cardId;
  return '<div class="card">'
    + '<div class="card-head"><span class="platform">' + esc(platform) + '</span>'
    + '<button class="copy-btn" data-target="' + id + '">Copy</button></div>'
    + (note ? '<div class="note">' + esc(note) + '</div>' : '')
    + '<pre id="' + id + '" class="caption">' + esc(body) + '</pre>'
    + '</div>';
};

const threadText = Array.isArray(c.twitter_thread)
  ? c.twitter_thread.map((t, i) => (i + 1) + '/' + c.twitter_thread.length + ' ' + t).join('\n\n')
  : '';

const attachNote = imageUrl ? 'Attach the featured image when posting' : '';

let cards = '';
cards += card('LinkedIn', c.linkedin, attachNote);
cards += card('Twitter / X (single post)', c.twitter, attachNote);
cards += card('Twitter / X (thread)', threadText, 'Post each numbered block as a separate tweet in one thread');
cards += card('Facebook', c.facebook, attachNote);
cards += card('Instagram', c.instagram, imageUrl ? 'Image required. Use the featured image above.' : 'Instagram needs an image. Add one before posting.');
cards += card('Threads', c.threads, attachNote);
if (c.pinterest) {
  cards += card('Pinterest title', c.pinterest.title, '');
  cards += card('Pinterest description', c.pinterest.description, imageUrl ? 'Image required. Use the featured image above.' : 'Pinterest needs an image. Add one before posting.');
}
cards += card('YouTube Community post', c.youtube_community, '');
if (c.reddit) {
  cards += card('Reddit title', c.reddit.title, '');
  cards += card('Reddit body', c.reddit.body, 'Check the subreddit rules on self-promotion before posting');
}
cards += card('Image alt text', c.image_alt_text, 'Paste this into the alt text field on any platform that supports it');

const imageBlock = imageUrl
  ? '<div class="imgwrap"><div class="imglabel">Featured image</div><img src="' + esc(imageUrl) + '" alt="' + esc(c.image_alt_text || '') + '"><div class="imgurl">' + esc(imageUrl) + '</div></div>'
  : '<div class="imgwrap noimg">No featured image was provided. Instagram and Pinterest both require an image before you can post.</div>';

const blogLine = blogUrl
  ? '<div class="bloglink">Source: <a href="' + esc(blogUrl) + '" target="_blank" rel="noopener">' + esc(blogUrl) + '</a></div>'
  : '';

const styles = 'body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:#f4f5f7;color:#1f2328;margin:0;padding:32px 16px}'
  + '*{box-sizing:border-box}'
  + '.wrap{max-width:820px;margin:0 auto}'
  + 'h1{font-size:24px;margin:0 0 6px}'
  + '.sub{color:#57606a;font-size:14px;margin-bottom:24px}'
  + '.bloglink{font-size:13px;margin-bottom:20px}.bloglink a{color:#0969da}'
  + '.imgwrap{background:#fff;border:1px solid #d8dee4;border-radius:10px;padding:16px;margin-bottom:24px}'
  + '.imgwrap.noimg{color:#9a6700;background:#fff8c5;border-color:#eac54f;font-size:14px}'
  + '.imglabel{font-size:12px;text-transform:uppercase;letter-spacing:.5px;color:#57606a;margin-bottom:10px}'
  + '.imgwrap img{max-width:100%;border-radius:8px;display:block}'
  + '.imgurl{font-size:12px;color:#57606a;margin-top:8px;word-break:break-all}'
  + '.card{background:#fff;border:1px solid #d8dee4;border-radius:10px;margin-bottom:16px;overflow:hidden}'
  + '.card-head{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;border-bottom:1px solid #eaeef2;background:#f6f8fa}'
  + '.platform{font-weight:600;font-size:14px}'
  + '.copy-btn{background:#1f2328;color:#fff;border:0;border-radius:6px;padding:6px 14px;font-size:13px;cursor:pointer}'
  + '.copy-btn:hover{background:#444c56}.copy-btn.done{background:#1a7f37}'
  + '.note{padding:8px 16px;font-size:12px;color:#9a6700;background:#fff8c5;border-bottom:1px solid #eaeef2}'
  + '.caption{margin:0;padding:16px;white-space:pre-wrap;word-wrap:break-word;font-family:inherit;font-size:14px;line-height:1.6}';

const script = 'document.querySelectorAll(".copy-btn").forEach(function(btn){'
  + 'btn.addEventListener("click",function(){'
  + 'var el=document.getElementById(btn.getAttribute("data-target"));'
  + 'var text=el.innerText;'
  + 'var done=function(){var old=btn.innerText;btn.innerText="Copied";btn.classList.add("done");'
  + 'setTimeout(function(){btn.innerText=old;btn.classList.remove("done");},1600);};'
  + 'if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(text).then(done);}'
  + 'else{var ta=document.createElement("textarea");ta.value=text;document.body.appendChild(ta);ta.select();'
  + 'document.execCommand("copy");document.body.removeChild(ta);done();}'
  + '});});';

const html = '<!DOCTYPE html><html><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width, initial-scale=1">'
  + '<title>Your Social Media Captions</title><style>' + styles + '</style></head><body><div class="wrap">'
  + '<h1>Your social media captions</h1>'
  + '<div class="sub">Copy any caption below and paste it on the platform. Nothing is posted automatically.</div>'
  + blogLine + imageBlock + cards
  + '</div><script>' + script + '<\/script></body></html>';

return [{ json: { html } }];
